import React, { useState, useEffect } from 'react';
import { historyApi } from '../utils/api';
import toast from 'react-hot-toast';

export default function HistoryView() {
  const [summary, setSummary] = useState(null);
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([historyApi.getSummary(), historyApi.getAll()])
      .then(([s, r]) => { setSummary(s); setRecords(r); })
      .catch(() => toast.error("Ma'lumot yuklanmadi"))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-32">
        <div className="w-8 h-8 border-2 border-violet-500 border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-gray-500">Yuklanmoqda...</p>
      </div>
    );
  }

  const catLabels = { starter: 'Salatlar', main: 'Asosiy', dessert: 'Desert', beverage: 'Ichimlik', combo: 'Kompleks' };

  return (
    <div className="space-y-6">
      {/* KPI cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <KpiCard icon="📦" label="Jami buyurtmalar" value={summary?.totalOrders ?? 0} color="violet" />
        <KpiCard icon="💵" label="Jami daromad" value={`$${(summary?.totalRevenue ?? 0).toFixed(2)}`} color="emerald" />
        <KpiCard icon="🧾" label="O'rtacha hisob" value={`$${(summary?.averageOrderValue ?? 0).toFixed(2)}`} color="amber" />
        <KpiCard icon="🏆" label="Eng ko'p buyurtma" value={summary?.topItems?.[0]?.name ?? '—'} small color="blue" />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Top items */}
        {summary?.topItems?.length > 0 && (
          <div className="card p-5">
            <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
              <span>🥇</span> Eng ko'p buyurtma qilingan taomlar
            </h3>
            <div className="space-y-3">
              {summary.topItems.map((item, i) => {
                const pct = Math.round((item.count / (summary.topItems[0]?.count || 1)) * 100);
                return (
                  <div key={i}>
                    <div className="flex justify-between text-sm mb-1">
                      <span className="text-gray-300 flex items-center gap-2">
                        <span className="text-gray-600 w-4 text-right">{i + 1}.</span>
                        {item.name}
                      </span>
                      <span className="text-emerald-400 font-semibold">{item.count}x</span>
                    </div>
                    <div className="h-1.5 bg-white/5 rounded-full overflow-hidden">
                      <div className="h-full bg-gradient-to-r from-violet-500 to-emerald-500 rounded-full"
                        style={{ width: `${pct}%`, transition: 'width 0.5s ease' }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Revenue by category */}
        {summary?.revenueByCategory && Object.keys(summary.revenueByCategory).length > 0 && (
          <div className="card p-5">
            <h3 className="text-white font-semibold mb-4 flex items-center gap-2">
              <span>📊</span> Kategoriya bo'yicha daromad
            </h3>
            <div className="space-y-3">
              {Object.entries(summary.revenueByCategory)
                .sort((a, b) => b[1] - a[1])
                .map(([cat, rev], i) => {
                  const maxRev = Math.max(...Object.values(summary.revenueByCategory));
                  const pct = Math.round((rev / maxRev) * 100);
                  return (
                    <div key={cat}>
                      <div className="flex justify-between text-sm mb-1">
                        <span className="text-gray-300">{catLabels[cat] || cat}</span>
                        <span className="text-amber-400 font-semibold">${rev.toFixed(2)}</span>
                      </div>
                      <div className="h-1.5 bg-white/5 rounded-full overflow-hidden">
                        <div className="h-full bg-gradient-to-r from-amber-500 to-orange-500 rounded-full"
                          style={{ width: `${pct}%` }} />
                      </div>
                    </div>
                  );
                })}
            </div>
          </div>
        )}
      </div>

      {/* Records table */}
      <div className="card">
        <div className="card-header">
          <h3 className="text-white font-semibold flex items-center gap-2">
            <span>📋</span> Buyurtmalar tarixi
          </h3>
          <span className="badge bg-white/5 text-gray-400">{records.length} ta yozuv</span>
        </div>

        {records.length === 0 ? (
          <div className="p-12 text-center">
            <p className="text-4xl mb-3">📭</p>
            <p className="text-gray-500">Hali hech qanday buyurtma amalga oshirilmagan</p>
            <p className="text-gray-700 text-sm mt-1">Buyurtma berib, hisob to'langanidan so'ng bu yerda ko'rinadi</p>
          </div>
        ) : (
          <div className="divide-y divide-white/[0.04] max-h-80 overflow-y-auto">
            {[...records].reverse().map((record, i) => (
              <div key={i} className="flex items-center justify-between px-5 py-3.5 hover:bg-white/[0.02] transition-colors">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-violet-500/15 flex items-center justify-center text-violet-400 text-xs font-mono font-bold">
                    {record.tableId}
                  </div>
                  <div>
                    <p className="text-white text-sm font-medium">#{record.orderId?.slice(0, 8)}</p>
                    <p className="text-gray-600 text-xs">{new Date(record.timestamp).toLocaleString('uz-UZ')}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-emerald-400 font-bold">${record.total?.toFixed(2)}</p>
                  <p className="text-gray-600 text-xs">{record.pricingStrategy}</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function KpiCard({ icon, label, value, color, small }) {
  const c = { violet: 'border-violet-500/20', emerald: 'border-emerald-500/20', amber: 'border-amber-500/20', blue: 'border-blue-500/20' };
  const t = { violet: 'text-violet-400', emerald: 'text-emerald-400', amber: 'text-amber-400', blue: 'text-blue-400' };
  return (
    <div className={`card border ${c[color]} p-5`}>
      <div className="flex justify-between items-start mb-2">
        <p className="text-gray-500 text-xs font-medium">{label}</p>
        <span className="text-xl">{icon}</span>
      </div>
      <p className={`font-bold ${small ? 'text-base truncate' : 'text-2xl'} ${t[color]}`}>{value}</p>
    </div>
  );
}
